-- PT107-S1-Q3. Batch 13.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT107-S1-Q3$batch13$ AND q.stimulus=$batch13$There should be a greater use of gasohol. Gasohol is a mixture of alcohol and gasoline, and has a higher octane rating and fewer carbon monoxide emissions than straight gasoline. Burning gasohol adds no more carbon dioxide to the atmosphere than plants remove by photosynthesis.$batch13$ AND q.prompt=$batch13$Each of the following, if true, strengthens the argument above EXCEPT:$batch13$ AND q.correct_choice=$batch13$C$batch13$) THEN RAISE EXCEPTION 'Question changed: PT107-S1-Q3'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch13$PT107-S1-Q3$batch13$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT107-S1-Q3'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT107-S1-Q3$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Conclusion$batch13$, $batch13$Gasohol should be used more.$batch13$), (1, $batch13$Evidence$batch13$, $batch13$Gasohol has a higher octane rating and lower carbon monoxide emissions than gasoline. Burning it adds no more carbon dioxide than plants remove.$batch13$), (2, $batch13$Evaluate$batch13$, $batch13$This is an EXCEPT question. Four choices give another reason to prefer gasohol over gasoline. The answer gives no such reason, or gives a reason against.$batch13$), (3, $batch13$Goal$batch13$, $batch13$Find the choice that doesn't favor gasohol.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT107-S1-Q3$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$Cars run better on gasohol. Another advantage.$batch13$), ($batch13$B$batch13$, $batch13$Gasohol saves gasoline, which makes an energy shortage less likely.$batch13$), ($batch13$C$batch13$, $batch13$Burning more gasohol per kilometer is a cost of gasohol, not a benefit. It doesn't help the argument.$batch13$), ($batch13$D$batch13$, $batch13$Gasohol is cheaper at the pump.$batch13$), ($batch13$E$batch13$, $batch13$The premise says gasohol adds no more CO2 than plants remove. If gasoline adds more than plants can remove, gasohol has a real advantage over gasoline.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT107-S1-Q3$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
